// services/orders.js - the only surface the HTTP layer imports
import { quote } from "../pricing/pricing.js";
import { reserve } from "../inventory/inventory.js";
import { insertOrder } from "../data/orders.js";

export async function placeOrder(req) {          // coarse-grained, one use case
  const q = await quote(req.sku, req.qty);
  await reserve(req.sku, req.qty);
  return insertOrder({ customerId: req.customerId, quote: q });
}
// fine-grained modules stay internal: package.json "exports" hides them
